const alumnes = [
  { nom: 'Aina', nota: 7 },
  { nom: 'Biel', nota: 4 },
  { nom: 'Carla', nota: 10 }
];
const aprovats = arr => arr.filter(a => a.nota >= 5).map(a => a.nom);
console.log(aprovats(alumnes));

const alumnes = [
  { nom: 'Aina', nota: 7 },
  { nom: 'Biel', nota: 4 },
